    internal static IEnumerable<string> Names=>entries.Keys;
    internal static bool IsOriginal(string name)=>name!=null&&entries.ContainsKey(name);
    internal static string Label(string clip)
    {
        if(!entries.TryGetValue(clip,out var entry))return clip;
        string text=entry.Key.Length>0?Localizer.Trans(entry.Key):entry.Words[ActionNames.Language];
        if(text==entry.Key)text=entry.Words[ActionNames.Language].Length>0?entry.Words[ActionNames.Language]:clip;
        var suffix=entry.Suffix[ActionNames.Language];
        return suffix.Length==0?text:text+" · "+suffix;
    }
